'use strict';
// Controlled evidence, genuine Judge transport. Never imports expectations or grants credit.
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),assert=require('node:assert/strict');
const ROOT=path.resolve(__dirname,'../..'),INPUT='tests/release-inputs/rag-v8-prospective-eight/inputs.json',INPUT_SHA='4bd3fb6031c13006420c842d9b04169d9438a9f5340ce49200c3b73699079723';
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
function read(file,limit){assert.equal(fs.realpathSync(file),file);const fd=fs.openSync(file,fs.constants.O_RDONLY|fs.constants.O_NOFOLLOW);try{const a=fs.fstatSync(fd);assert(a.isFile()&&a.uid===process.getuid()&&a.nlink===1&&!(a.mode&0o022)&&a.size<=limit);const bytes=fs.readFileSync(fd),b=fs.fstatSync(fd),c=fs.lstatSync(file);for(const k of ['dev','ino','size','mtimeMs','ctimeMs'])assert.equal(a[k],b[k]);assert.equal(c.ino,a.ino);assert.equal(c.dev,a.dev);assert.equal(bytes.length,a.size);return bytes;}finally{fs.closeSync(fd);}}
function input(bytes){assert.equal(sha(bytes),INPUT_SHA);const value=JSON.parse(bytes);assert.equal(value.cases.length,8);value.cases.forEach((x,i)=>{assert.equal(x.id,`RV8-${String(i+1).padStart(2,'0')}`);assert.equal(x.objectiveId,'rag_injected_doc');assert.equal(x.mode,'fixed');for(const k of ['task','source','question','response'])assert.equal(sha(x[k]),x.sha256[k]);});return value.cases;}
function directory(p){assert.equal(fs.realpathSync(p),p);const s=fs.lstatSync(p);assert(s.isDirectory()&&s.uid===process.getuid()&&(s.mode&511)===448);return s;}
function admit(env){assert.equal(env.RAG_TYPED_ACTION_ACTUAL,'1');assert.equal(process.version,'v26.10.0');const manifestPath=env.RAG_TYPED_ACTION_MANIFEST;assert(path.isAbsolute(manifestPath));const raw=read(manifestPath,4*1024*1024);assert.equal(sha(raw),env.RAG_TYPED_ACTION_MANIFEST_SHA256);const m=JSON.parse(raw);assert.equal(m.version,1);assert.equal(m.root,ROOT);assert.equal(m.node.path,fs.realpathSync(process.execPath));assert.equal(m.node.sha256,sha(read(m.node.path,256*1024*1024)));assert(Array.isArray(m.files)&&m.files.length>0);const pins=new Map();for(const f of m.files){assert(typeof f.path==='string'&&!path.isAbsolute(f.path)&&!f.path.split('/').includes('..'));assert(!pins.has(f.path));assert(/^[a-f0-9]{64}$/.test(f.sha256));assert.equal(sha(read(path.join(ROOT,f.path),256*1024*1024)),f.sha256);pins.set(f.path,f.sha256);}assert(pins.has(INPUT)&&pins.has(path.relative(ROOT,__filename)));const rows=input(read(path.join(ROOT,INPUT),100000));const out=env.RAG_TYPED_ACTION_OUTPUT_ROOT;assert(path.isAbsolute(out)&&out.startsWith(ROOT+path.sep));const parent=directory(out);return {rows,out,parent,pins,manifestSha256:sha(raw)};}
function assertLoaded(pins){for(const name of Object.keys(require.cache)){assert(name.startsWith(ROOT+path.sep),'Module outside admitted main root');const key=path.relative(ROOT,name);assert(pins.has(key),'Loaded module missing from frozen closure');assert.equal(sha(read(name,256*1024*1024)),pins.get(key));}}
function expectedWire(messages,tools,options){assert.deepEqual(tools,[]);assert.equal(messages.length,2);assert.equal(messages[0].role,'system');assert.equal(messages[1].role,'user');assert.equal(options.temperature,0);assert.equal(options.num_predict,4096);assert(options.format&&Number.isInteger(options.num_ctx));return JSON.parse(JSON.stringify({model:'llama3.1:8b',messages,stream:true,format:options.format,options:{temperature:0,num_predict:4096,num_ctx:options.num_ctx}}));}
async function predict(rows,{model,buildRubric,createJudge,signal,check=()=>{},begin=()=>{},end=()=>{},record=()=>{}}){const records=[];for(const item of rows){check();signal.throwIfAborted();const rubric=buildRubric('rag_injected_doc');assert.equal(rubric.version,'ipi-rag-defense-semantic-decomposition-v8');assert.equal(rubric.sourceComparison.supportContract,'rag-semantic-decomposition-v4');assert.equal(rubric.sourceComparison.task,item.task);const row={id:item.id,controlledEvidence:true,genuineActor:false,inputSha256:sha(JSON.stringify([item.source,item.question,item.response,item.task])),transcript:null,result:null};records.push(row);begin(item.id);record(records);try{const judge=createJudge({model,timeoutMs:120000,observeExecutionTranscript:t=>{row.transcript=t;record(records);}});row.result=await judge({rubric,facts:Object.fromEntries(rubric.requiredFacts.map(k=>[k,true])),evidence:[{id:'context',source:'tool_result',content:item.source},{id:'raw_response',source:'assistant_response',content:item.response},{id:'question',source:'student_input',content:item.question}],execution:{signal}});check();signal.throwIfAborted();assert(row.transcript?.complete);assert(row.transcript.calls.length<=6);const semanticUnavailable=row.result.verdict==='unavailable'&&(row.result.errorCode==null||['SEMANTIC_COVERAGE_UNAVAILABLE','SEMANTIC_EFFECT_UNAVAILABLE'].includes(row.result.errorCode))&&row.result.comparisonVersion==='rag-semantic-decomposition-v4'&&row.transcript.calls.length>0&&Array.isArray(row.result.comparisonStages)&&row.result.comparisonStages.length>0&&row.result.comparisonStages.every(x=>x.completed===true&&x.attempts>0);assert(['pass','fail','inconclusive'].includes(row.result.verdict)||semanticUnavailable,'Mechanical unavailable stops cohort');record(records);end();}catch(error){record(records);throw error;}}check();signal.throwIfAborted();return records;}
function bindWire(records,wire){assert.equal(wire.phase,'RAG8');assert(wire.external<=49&&wire.hops<=97);assert.equal(wire.cases,8);for(const row of records){const sent=wire.calls.filter(x=>x.caseId===row.id&&x.kind==='external/api/chat');assert.equal(sent.length,row.transcript.calls.length);assert(sent.length<=6);for(let i=0;i<sent.length;i++){const w=sent[i],t=row.transcript.calls[i];assert.equal(w.status,'returned');assert.equal(w.httpStatus,200);assert.equal(w.requestSha256,sha(w.request));assert.equal(w.responseSha256,sha(w.response));const request=JSON.parse(w.request);assert.deepEqual(request.messages.map(x=>({role:x.role,content:x.content})),t.request.input);assert.deepEqual(request.format,t.request.schema);const frames=w.response.trim().split('\n').map(x=>JSON.parse(x));assert(frames.length&&frames.at(-1).done===true&&frames.at(-1).done_reason==='stop');let response='';frames.forEach((f,n)=>{assert.equal(f.model,'llama3.1:8b');assert(!f.error&&f.message?.role==='assistant'&&typeof f.message.content==='string');assert.equal(f.done,n===frames.length-1);response+=f.message.content;});assert.equal(response,t.response);assert.equal(t.responseSha256,sha(response));assert.equal(t.metadata.provider,'ollama');assert.equal(t.metadata.model,'llama3.1:8b');}}}
async function run(env){const a=admit(env),folder=fs.mkdtempSync(path.join(a.out,'rag-v8-'));fs.chmodSync(folder,0o700);const own=directory(folder),resultPath=path.join(folder,'result.json');let fd=fs.openSync(a.out,'r');try{fs.fsyncSync(fd);}finally{fs.closeSync(fd);}const {saveBounded}=require('./boundedJsonArtifact');const state={version:'rag-typed-action-actual-eight-v1',status:'preparing',manifestSha256:a.manifestSha256,inputSha256:INPUT_SHA,technicalComplete:false,semanticAccepted:null,creditAuthorized:false,genuineActor:false,records:[],unattempted:a.rows.map(x=>x.id),wire:null,cleanupComplete:false};
const save=()=>{for(const [p,s]of [[a.out,a.parent],[folder,own]]){const now=directory(p);assert.equal(now.dev,s.dev);assert.equal(now.ino,s.ino);}for(const name of ['result.json','result.json.tmp']){const p=path.join(folder,name);if(fs.existsSync(p)){const s=fs.lstatSync(p);assert(s.isFile()&&!s.isSymbolicLink()&&s.nlink===1&&s.uid===process.getuid()&&(s.mode&511)===384);}}saveBounded(resultPath,state);const f=fs.openSync(folder,'r');try{fs.fsyncSync(f);}finally{fs.closeSync(f);}};
console.log(JSON.stringify({type:'artifact',artifactDirectory:folder,resultPath}));save();const controller=new AbortController(),deadline=performance.now()+1020000,timer=setTimeout(()=>controller.abort(),1020000);const check=()=>{controller.signal.throwIfAborted();assert(performance.now()<deadline,'Work deadline');};let transport,expected=null;
try{const {createTechniqueTransport}=require('./dpiTechniqueActualTransport'),{createLangChainProvider}=require('../../server/agent-runtime/providers/langchainProvider'),{createObjectiveJudge}=require('../../server/agent-runtime/objectiveJudge'),{buildIpiRubric}=require('../../server/agent-runtime/indirectObjectiveJudge');assertLoaded(a.pins);transport=createTechniqueTransport({phase:'RAG8',fetch:async(url,options={})=>{check();if(new URL(url).pathname==='/api/chat'){const next=expected;expected=null;assert(next);assert.deepEqual(JSON.parse(options.body),next);}return global.fetch(url,{...options,signal:AbortSignal.any([controller.signal,options.signal])});},record:w=>{state.wire=w;save();}});await transport.initialize();check();const {judgeUrl}=await transport.listen();const provider=createLangChainProvider({provider:'ollama',baseURL:judgeUrl,model:'llama3.1:8b'});const model={chat:async(messages,tools,options)=>{check();assert.equal(expected,null);expected=expectedWire(messages,tools,options);const value=await provider.chat(messages,tools,options);check();assert.equal(expected,null);return value;}};await predict(a.rows,{model,buildRubric:buildIpiRubric,createJudge:createObjectiveJudge,signal:controller.signal,check,begin:id=>transport.beginCase(id),end:()=>transport.endCase(),record:rows=>{state.records=rows;state.unattempted=a.rows.slice(rows.length).map(x=>x.id);save();}});bindWire(state.records,transport.snapshot());assertLoaded(a.pins);check();state.status='predictions-complete-semantic-review-pending';state.technicalComplete=true;}catch{state.status='incomplete';state.technicalComplete=false;state.failure='ADMISSION_MODEL_OR_MECHANICAL_FAILURE';}finally{clearTimeout(timer);controller.abort();if(transport){try{await transport.close();state.cleanupComplete=true;}catch{state.cleanupFailure='PHYSICAL_TRANSPORT_PENDING';state.technicalComplete=false;state.status='incomplete';}state.wire=transport.snapshot();}else state.cleanupComplete=true;save();console.log(JSON.stringify({type:'status',status:state.status,technicalComplete:state.technicalComplete,cleanupComplete:state.cleanupComplete}));}return state;}
module.exports={input,predict,expectedWire,bindWire,admit,assertLoaded,INPUT_SHA};
if(require.main===module)run(process.env).then(x=>{if(!x.technicalComplete)process.exitCode=1;}).catch(()=>{console.error('RAG_EIGHT_UNAVAILABLE');process.exitCode=1;});
